#include <cmath>
#include <cstdint>
#include <format>
#include <iostream>
#include <numbers>
#include <vector>

// A pose on the floor, in the odometry frame.
struct Pose {
  double x_m;
  double y_m;
  double yaw_rad;
};

// One step of wheel motion, already turned into a distance and a heading change by the encoder
// arithmetic bench_core does. Both travel together so they cannot be swapped.
struct Step {
  double distance_m;
  double turn_rad;
};

// The update almost everybody writes first: move along the heading you had, then turn.
[[nodiscard]] Pose straight_line(Pose from, Step step) {
  return Pose{.x_m = from.x_m + step.distance_m * std::cos(from.yaw_rad),
              .y_m = from.y_m + step.distance_m * std::sin(from.yaw_rad),
              .yaw_rad = from.yaw_rad + step.turn_rad};
}

// The arc the wheels actually drove: constant speed and constant turn rate over the step is a
// circle, and integrating it exactly costs two more trigonometric calls.
[[nodiscard]] Pose exact_arc(Pose from, Step step) {
  if (std::abs(step.turn_rad) < 1e-12) return straight_line(from, step);
  const double radius_m = step.distance_m / step.turn_rad;
  const double to_yaw = from.yaw_rad + step.turn_rad;
  return Pose{.x_m = from.x_m + radius_m * (std::sin(to_yaw) - std::sin(from.yaw_rad)),
              .y_m = from.y_m - radius_m * (std::cos(to_yaw) - std::cos(from.yaw_rad)),
              .yaw_rad = to_yaw};
}

[[nodiscard]] double distance_between(Pose a, Pose b) {
  return std::hypot(a.x_m - b.x_m, a.y_m - b.y_m);
}

int main() {
  // A quarter circle of radius 0.5 m, driven at 0.2 m/s: the arc is 0.7854 m and takes 3.93 s.
  constexpr double radius_m = 0.5;
  constexpr double quarter_turn_rad = std::numbers::pi / 2.0;
  constexpr double arc_m = radius_m * quarter_turn_rad;
  const Pose start{.x_m = 0.0, .y_m = 0.0, .yaw_rad = 0.0};
  const Pose truth{.x_m = radius_m, .y_m = radius_m, .yaw_rad = quarter_turn_rad};

  std::cout << std::format("a quarter circle of radius {:.2f} m, ending at ({:.4f}, {:.4f})\n\n", radius_m,
                           truth.x_m, truth.y_m);
  std::cout << std::format("{:>6} {:>8} {:>26} {:>26}\n", "rate", "step", "straight-line error", "exact-arc error");
  for (const std::int64_t rate_hz : std::vector<std::int64_t>{5, 10, 20, 30, 50}) {
    const double seconds = arc_m / 0.2;
    const auto steps = static_cast<std::int64_t>(std::llround(seconds * static_cast<double>(rate_hz)));
    const Step step{.distance_m = arc_m / static_cast<double>(steps),
                    .turn_rad = quarter_turn_rad / static_cast<double>(steps)};

    Pose naive = start;
    Pose exact = start;
    for (std::int64_t i = 0; i < steps; ++i) {
      naive = straight_line(naive, step);
      exact = exact_arc(exact, step);
    }
    std::cout << std::format("{:>4}Hz {:>7.1f}ms {:>23.4f} m {:>23.6f} m\n", rate_hz, 1000.0 / static_cast<double>(rate_hz),
                             distance_between(naive, truth), distance_between(exact, truth));
  }
}

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <string_view>
#include <vector>

// A motor and a wheel, as a first-order lag: the speed chases the commanded speed with a time
// constant. This is the simplest plant that behaves like the real one, and the point of a
// simulated plant is that a test of the controller needs no robot and no clock.
class Motor {
 public:
  Motor(double time_constant_s, double step_s) : time_constant_s_(time_constant_s), step_s_(step_s) {}

  void apply(double command_mps) {
    speed_mps_ += (step_s_ / time_constant_s_) * (command_mps - speed_mps_);
  }

  [[nodiscard]] double speed_mps() const { return speed_mps_; }

 private:
  double time_constant_s_;
  double step_s_;
  double speed_mps_ = 0.0;
};

// What to do with the integral when the actuator is already at its limit. The names are the ones
// control_toolbox uses for the same choice.
enum class Antiwindup { None, ConditionalIntegration };

struct Gains {
  double p;
  double i;
  double d;
};

// A PID with an output limit, because every real actuator has one and leaving it out is how the
// integral term learns to lie. Time arrives as an argument, so a test replays any timeline.
class Pid {
 public:
  Pid(Gains gains, double limit, Antiwindup antiwindup)
      : gains_(gains), limit_(limit), antiwindup_(antiwindup) {}

  [[nodiscard]] double command(double error, double step_s) {
    const double derivative = (step_s > 0.0) ? (error - last_error_) / step_s : 0.0;
    const double candidate_integral = integral_ + error * step_s;
    const double unclamped =
        gains_.p * error + gains_.i * candidate_integral + gains_.d * derivative;
    const double clamped = std::clamp(unclamped, -limit_, limit_);

    // Conditional integration: stop adding to the integral while the output is against its limit
    // and the error would push it further that way.
    const bool winding_up = antiwindup_ == Antiwindup::ConditionalIntegration && unclamped != clamped &&
                            ((unclamped > 0.0) == (error > 0.0));
    if (!winding_up) integral_ = candidate_integral;
    last_error_ = error;
    return clamped;
  }

  [[nodiscard]] double integral() const { return integral_; }

 private:
  Gains gains_;
  double limit_;
  Antiwindup antiwindup_;
  double integral_ = 0.0;
  double last_error_ = 0.0;
};

struct Run {
  double final_error_mps;
  double overshoot_percent;
  std::optional<double> settled_s;  // first time it stayed within 2% to the end
  double worst_integral;
};

[[nodiscard]] Run drive(Gains gains, double limit, Antiwindup antiwindup, double target_mps) {
  constexpr double step_s = 0.05;   // a 20 Hz control loop, the rate the bench's supervisor runs at
  constexpr std::int64_t steps = 200;  // ten seconds
  Motor motor(0.30, step_s);
  Pid pid(gains, limit, antiwindup);

  double highest = 0.0;
  double worst_integral = 0.0;
  std::optional<double> settled_s;
  for (std::int64_t k = 0; k < steps; ++k) {
    const double command = pid.command(target_mps - motor.speed_mps(), step_s);
    motor.apply(command);
    highest = std::max(highest, motor.speed_mps());
    worst_integral = std::max(worst_integral, std::abs(pid.integral()));
    const bool within = std::abs(motor.speed_mps() - target_mps) <= 0.02 * target_mps;
    if (!within) {
      settled_s.reset();
    } else if (!settled_s) {
      settled_s = static_cast<double>(k + 1) * step_s;
    }
  }
  return Run{.final_error_mps = motor.speed_mps() - target_mps,
             .overshoot_percent = 100.0 * (highest - target_mps) / target_mps,
             .settled_s = settled_s,
             .worst_integral = worst_integral};
}

struct Case {
  std::string_view what;
  Gains gains;
  double limit;
  Antiwindup antiwindup;
};

int main() {
  constexpr double target_mps = 1.0;
  std::cout << std::format("{:<38} {:>12} {:>15} {:>9} {:>10}\n", "controller", "final error",
                           "peak vs target", "settled", "integral");
  for (const Case& one : std::vector<Case>{
           {.what = "P only, Kp 2", .gains = {.p = 2.0, .i = 0.0, .d = 0.0}, .limit = 10.0,
            .antiwindup = Antiwindup::None},
           {.what = "PI, Kp 2 Ki 4", .gains = {.p = 2.0, .i = 4.0, .d = 0.0}, .limit = 10.0,
            .antiwindup = Antiwindup::None},
           {.what = "PI, Ki 20, output limited to 1.2", .gains = {.p = 2.0, .i = 20.0, .d = 0.0},
            .limit = 1.2, .antiwindup = Antiwindup::None},
           {.what = "the same, conditional integration", .gains = {.p = 2.0, .i = 20.0, .d = 0.0},
            .limit = 1.2, .antiwindup = Antiwindup::ConditionalIntegration},
           {.what = "the same, plus Kd 0.1", .gains = {.p = 2.0, .i = 20.0, .d = 0.1},
            .limit = 1.2, .antiwindup = Antiwindup::ConditionalIntegration}}) {
    const Run run = drive(one.gains, one.limit, one.antiwindup, target_mps);
    const std::string settled =
        run.settled_s ? std::format("{:.2f}s", *run.settled_s) : std::string{"never"};
    std::cout << std::format("{:<38} {:>+11.4f} {:>+14.1f}% {:>9} {:>10.3f}\n", one.what, run.final_error_mps,
                             run.overshoot_percent, settled, run.worst_integral);
  }
}
